# Simplified, correct approach
def find_square_frames_v2(grid):
    """Find all square frames correctly"""
    h, w = len(grid), len(grid[0])
    found_frames = []
    visited = [[False]*w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or visited[r][c]:
                continue

            # Try to find a frame starting at (r,c)
            start_color = grid[r][c]

            # Expand from (r,c) in horizontal direction
            c_max = c
            while c_max < w and grid[r][c_max] == start_color:
                if c_max - c >= 3:  # Need at least 3 wide
                    # Try expanding vertically from current width
                    for _ in range(200):  # Limit iterations
                        r_min, r_max = r, r
                        c_min, c_max = c, c

                        # Expand left
                        test_c_min = c_min - 1
                        while test_c_min >= c and grid[r][test_c_min] == start_color:
                            # Check top and bottom at this column
                            if r > 0 and grid[r-1][test_c_min] == start_color and r_max < h and grid[r_max][test_c_min] == start_color:
                                c_min -= 1
                            else:
                                break

                        # Expand right  
                        test_c_max = c_max + 1
                        while test_c_max < w and grid[r][test_c_max] == start_color:
                            if r > 0 and grid[r-1][test_c_max] == start_color and r_max < h and grid[r_max][test_c_max] == start_color:
                                c_max += 1
                            else:
                                break

                        # Expand up
                        if r_min >= 0 and grid[r_min-1][c_min] == start_color and grid[r_min-1][c_max] == start_color:
                            r_min -= 1
                        else:
                            break

                        # Expand down
                        if r_max < h and grid[r_max+1][c_min] == start_color and grid[r_max+1][c_max] == start_color:
                            r_max += 1
                        else:
                            break

                        h_frame = r_max - r_min + 1
                        w_frame = c_max - c_min + 1

                        if h_frame == w_frame and h_frame >= 3:
                            # Verify it's a frame (not filled)
                            is_frame = True
                            for rr in range(r_min, r_max+1):
                                for cc in range(c_min, c_max+1):
                                    on_border = (rr == r_min or rr == r_max or cc == c_min or cc == c_max)
                                    if on_border:
                                        if grid[rr][cc] != start_color:
                                            is_frame = False
                                    else:
                                        if grid[rr][cc] == start_color:
                                            is_frame = False

                            if is_frame:
                                inner_h = h_frame - 2
                                inner_w = w_frame - 2
                                fill = 2 if inner_h <= 2 and inner_w <= 2 else 7

                                # Mark visited
                                for rr in range(r_min, r_max+1):
                                    for cc in range(c_min, c_max+1):
                                        visited[rr][cc] = True

                                found_frames.append((start_color, r_min, c_min, fill, inner_h, inner_w))
                                break

            if found_frames:
                break

    return found_frames

