import json
from collections import deque

def find_connected_component(grid, start_r, start_c, color):
    visited = set()
    component = []
    queue = [(start_r, start_c)]

    while queue:
        r, c = queue.pop()
        if (r, c) in visited:
            continue
        visited.add((r, c))
        component.append((r, c))

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == color and (nr, nc) not in visited:
                    queue.append((nr, nc))

    return component

def transform(grid):
    """Fill hollow rectangular frames with BG color."""
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]  # Background color

    result = [row[:] for row in grid]

    def find_component(r, c, color):
        visited = set()
        queue = [(r, c)]
        comp = []
        while queue:
            cr, cc = queue.pop()
            if (cr, cc) in visited:
                continue
            visited.add((cr, cc))
            comp.append((cr, cc))
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < h and 0 <= nc < w:
                    if grid[nr][nc] == color and (nr, nc) not in visited:
                        queue.append((nr, nc))
        return comp

    # Find all connected components for each color (excluding background)
    visited_global = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and (r, c) not in visited_global:
                # Check if this forms a valid hollow rectangle
                comp = find_component(r, c, grid[r][c])
                visited_global.update(comp)

                if len(comp) < 8:
                    continue

                # Check if it's a hollow frame
                min_r = min(cell[0] for cell in comp)
                min_c = min(cell[1] for cell in comp)
                max_r = max(cell[0] for cell in comp)
                max_c = max(cell[1] for cell in comp)

                height = max_r - min_r + 1
                width = max_c - min_c + 1
                expected_border = 2 * height + 2 * width - 4
                interior_cells = len(comp) - expected_border

                # Valid hollow frame: all cells on border, no interior cells
                if expected_border == len(comp) and interior_cells == 0 and height >= 3 and width >= 3:
                    border_cells = sum(1 for cell in comp if cell[0] == min_r or cell[0] == max_r or cell[1] == min_c or cell[1] == max_c)
                    if border_cells == len(comp):
                        # Fill interior with bg
                        for fill_r in range(min_r + 1, max_r):
                            for fill_c in range(min_c + 1, max_c):
                                if result[fill_r][fill_c] == bg:
                                    result[fill_r][fill_c] = bg

    return result

