                        if grid[nr][nc] == frame_color and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))

        if not visited - {start}:
            return None
        min_r = min(r for r, c in visited)
        max_r = max(r for r, c in visited)
        min_c = min(r for r, c in visited)
        max_c = max(c for r, c in visited)

        return (min_r, min_c, max_r, max_c, frame_color)

